99		if !foundIntent {
100			t.Error("the non-redacted checkpoint's intent should still be usable output")
101		}
102	
103		// 2. The interface must clearly distinguish complete from incomplete
104		// context, and must never quietly present the gap as a complete result.
105		if !packetHasIncompleteSection(p) {
106			t.Fatal("a packet built over a redacted checkpoint must mark at least one section Incomplete")
107		}
108	
109		var md strings.Builder
110		if err := RenderMarkdown(&md, p); err != nil {
111			t.Fatalf("RenderMarkdown: %v", err)
112		}
113		if !strings.Contains(md.String(), "Incomplete context") {
114			t.Error("markdown output must visibly warn about incomplete context, not just carry a hidden flag")
115		}
116	}
