118	// TestPrivacyBoundary_CompleteRangeIsNeverFlaggedIncomplete guards the other
119	// direction of the same claim: a range with nothing missing must not be
120	// mislabelled, which would train a reader to ignore the warning.
121	func TestPrivacyBoundary_CompleteRangeIsNeverFlaggedIncomplete(t *testing.T) {
122		t.Parallel()
123	
124		p := Build(context.Background(), testInput(), true)
125		if packetHasIncompleteSection(p) {
126			t.Error("a fully-populated checkpoint range must not be marked incomplete")
127		}
128	}
