130	// TestPrivacyBoundary_AskQueryIsRedactedBeforeLeavingTheProcess is the other
131	// half of the Curveball: raw prompts must not reach the new external service.
132	// --ask is typed verbatim by the user, so it is exactly the "raw prompt" the
133	// security team is worried about.
134	func TestPrivacyBoundary_AskQueryIsRedactedBeforeLeavingTheProcess(t *testing.T) {
135		t.Parallel()
136	
137		s := &fakeSearcher{}
138		if _, err := newGlobalMemoryExtractor(s, "why did "+redactableSecret+" get committed").
139			Extract(context.Background(), intentInput()); err != nil {
140			t.Fatalf("Extract: %v", err)
141		}
142		if strings.Contains(s.gotText, redactableSecret) {
143			t.Errorf("raw secret reached the outgoing query text: %q", s.gotText)
144		}
145		if s.gotText == "" {
146			t.Error("the query never reached the searcher at all; this test would pass for the wrong reason")
147		}
148	}
